import { visiblePuzzleObjective } from './puzzle-copy.js';
import { encounterScene, encounterDone } from './road-ui.js';
import { PARTY_NAMES } from './road-cast.js';
import { companionDrawing } from './caravan-art.js';
import { media, slots } from './art.js';
import {isExpansion,mechanicFor,playInstructions} from './expansion.js';
import { BANDS, freshAttempt, isSolved, nextHint } from './engine.js';
export const symbols=['●','▲','■','★','◆','✚'], avatars=['✦','☀','❋','◆','☾','✿'];
export const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const btn=(label,action,cls='',extra='')=>`<button type="button" class="${cls}" data-action="${action}" data-focus="action-${action}" ${extra}>${label}</button>`;
export const bandOptions=band=>['k1','23','45'].map(key=>[key,BANDS[key]]).map(([key,b])=>`<label class="grade-option"><input type="radio" name="band" value="${key}" ${key===band?'checked':''}><strong>${b.label}</strong></label>`).join('');
export const listFor=(puzzles,band)=>puzzles.filter(p=>p.band===band).sort((a,b)=>band==='all'?a.mechanic.localeCompare(b.mechanic)||a.number-b.number:band==='proofs'?(a.libraryFamily==='tile'?0:1)-(b.libraryFamily==='tile'?0:1)||a.number-b.number:a.number-b.number||(a.mechanic==='tile'?-1:1));
export const count=(puzzles,pr)=>listFor(puzzles,pr.band).filter(p=>pr.attempts[p.id]?.completed).length;
export function nextPuzzle(puzzles,pr){const list=listFor(puzzles,pr.band);return list.filter(p=>pr.attempts[p.id]&&!isSolved(p,pr.attempts[p.id].board)).sort((a,b)=>pr.attempts[b.id].lastPlayed-pr.attempts[a.id].lastPlayed)[0]||list.find(p=>!pr.attempts[p.id]?.completed)||list[0];}
export function header(pr){return `<header class="topbar"><button class="brand" data-action="home" aria-label="Small math adventure home"><span class="brand-mark" aria-hidden="true"><i></i><b></b><b></b></span><strong>Small math<br>adventure</strong></button><nav class="nav-actions" aria-label="Main navigation">${pr?btn(`<span class="avatar" aria-hidden="true">${avatars[pr.avatar]}</span><span class="profile-label">${esc(pr.name)}</span>`,'profiles','profile-nav'):''}${btn('Grown-ups','parents-gate','quiet')}</nav></header>`;}
export function profilesView(state,puzzles){return `<section class="welcome"><p class="eyebrow">The little island expedition</p><h1>${state.profiles.length?'Welcome back,<br>explorer.':'Which way will<br>your mind wander?'}</h1><p class="muted">Explore gardens, lanterns, secret signals, and more.<br>Twelve kinds of mathematical adventure.</p>${state.profiles.length?`<div class="saved-profiles">${state.profiles.map(pr=>`<button class="profile-card" data-action="choose-profile" data-id="${esc(pr.id)}"><span class="avatar" aria-hidden="true">${avatars[pr.avatar]}</span><strong>${esc(pr.name)}</strong><span>Grades ${BANDS[pr.band].label} · ${count(puzzles,pr)} of 24 explored</span></button>`).join('')}</div><details class="panel add-profile"><summary>Create another explorer</summary>${profileForm()}</details>`:`<div class="panel profile-form">${profileForm()}</div>`}</section>`;}
function profileForm(){return `<form id="profile-form"><div class="form-row"><label class="field" for="nickname">Explorer’s nickname</label><input class="text-input" id="nickname" name="name" placeholder="What should we call you?" maxlength="24" autocomplete="off" required></div><fieldset class="avatar-picker"><legend class="field">Pick a little symbol</legend>${avatars.map((a,i)=>`<label><input type="radio" name="avatar" value="${i}" ${i===0?'checked':''}><span aria-label="Symbol ${i+1}">${a}</span></label>`).join('')}</fieldset><fieldset><legend class="field">Choose a starting trail</legend><div class="grade-options">${bandOptions('k1')}</div></fieldset><div class="form-actions"><span class="muted">24 trail puzzles + 60 family adventures</span><button class="primary" type="submit">Let’s explore ↗</button></div><p class="form-note muted">Choose by comfort, not age. All ten new puzzle families are available on every trail.</p></form>`;}
export function mapView(pr,puzzles){const list=listFor(puzzles,pr.band),next=nextPuzzle(puzzles,pr),done=count(puzzles,pr);return `<section class="intro"><div><p class="eyebrow">${BANDS[pr.band].name} · Grades ${BANDS[pr.band].label}</p><h1>Your island of ideas.</h1><p class="muted">A little wondering. A new way to see.</p>${btn('Explore the ten new families ↓','families','text-button')}</div>${btn('Change trail','change-band','secondary')}</section><div class="expedition-layout"><aside class="expedition-card"><div class="island-diagram" aria-hidden="true"><div class="island island-one"><span>▰</span><i>1</i></div><div class="island island-two"><span>⇄</span><i>2</i></div><div class="island island-three"><span>✦</span><i>3</i></div><svg viewBox="0 0 260 210"><path d="M70 65C220 5 220 100 130 110S20 165 170 175" fill="none" stroke="#779dbe" stroke-width="3" stroke-dasharray="5 8"/></svg></div><h2>${done===24?'A whole island of discoveries!':'A small adventure<br>is waiting.'}</h2><p class="muted">${done===24?'Replay a favorite, or try another trail.':'Try a puzzle or two. There’s no timer and no hurry.'}</p><div class="progress-label"><strong>${done} of 24</strong><span>explored</span></div><progress value="${done}" max="24" aria-label="Puzzles completed">${done}/24</progress>${btn(`${pr.attempts[next.id]&&!isSolved(next,pr.attempts[next.id].board)?'Continue':'Explore'}: ${esc(next.title)} ↗`,'open-puzzle','primary wide',`data-id="${next.id}"`)}</aside><div class="chapters">${[0,1,2].map(ch=>`<section class="chapter"><div class="chapter-heading"><span class="chapter-index">0${ch+1}</span><div><p class="eyebrow">${['First steps','Look a little closer','Make a discovery'][ch]}</p><h2>${['The landing','The winding paths','The lookout'][ch]}</h2></div><span class="chapter-count">${list.slice(ch*8,ch*8+8).filter(p=>pr.attempts[p.id]?.completed).length}/8</span></div><div class="puzzle-grid">${list.slice(ch*8,ch*8+8).map((p,i)=>{const a=pr.attempts[p.id],n=ch*8+i+1;return `<button class="puzzle-card ${p.mechanic} ${a?.completed?'complete':''}" data-action="open-puzzle" data-id="${p.id}" aria-label="${n}. ${esc(p.title)}. ${a?.completed?'Completed':a?'In progress':'Ready to explore'}"><span class="puzzle-top"><span class="mechanic-symbol" aria-hidden="true">${p.mechanic==='tile'?'▰':'⇄'}</span><span>${a?.completed?'✓':String(n).padStart(2,'0')}</span></span><strong>${esc(p.title)}</strong><small>${p.mechanic==='tile'?'Tile garden':'Cup swaps'}${a?.completed?' · Explored':a?' · Started':''}</small></button>`;}).join('')}</div></section>`).join('')}</div></div>${expansionMap(pr,puzzles)}`;}
function puzzleView(p,a,ctx){
  const expansion=isExpansion(p),solved=isSolved(p,a.board),hint=nextHint(p,a);
  const objective=visiblePuzzleObjective(p);
  ctx={...ctx,highlighted:a.hintLevel>=2&&hint.type==='move'?hint.pair:null};
  const feedback=ctx.message||(!solved&&hint.type==='deadend'&&!a.hintLevel?(expansion?hint.text:'This leaves an unfillable gap. Undo or lift a tile.'):'');
  return `${solved&&ctx.encounter?encounterDone(ctx.encounter,ctx.profile,p,a,ctx.result):''}<div class="play-heading">
    ${a.completed&&!solved?'<span class="solved-indicator">✓ Solved</span>':''}<div class="play-help">${btn('How to play','demo','quiet')}${btn('<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M11 4 6 8H3v8h3l5 4V4Z"/><path d="M15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/></svg>','speak','quiet small','aria-label="Read instructions aloud"')}</div>
  </div>
  <div class="play-layout ${expansion?'expansion-layout':''} ${solved?'is-complete':''}">
    <section class="board-panel ${expansion?'expansion-board':''} ${esc(p.mechanic)}" aria-label="Puzzle play area">
      ${objective?`<h1 class="puzzle-goal">${esc(objective)}</h1>`:`<h1 class="sr-only">${esc(p.familyTitle||(p.mechanic==='swap'?'Cup swaps':'Puzzle'))}</h1>`}
      ${expansion?mechanicFor(p).render(p,a,ctx):p.mechanic==='tile'?tileBoard(p,a,ctx):ctx.encounter?.party?partyBoard(p,a,ctx):swapBoard(p,a,ctx)}
      ${p.mechanic==='tile'?`<div class="board-bottom"><label class="checker-toggle"><input type="checkbox" id="checker" ${ctx.checker?'checked':''}> Checker colors</label></div>`:''}
    </section>
    ${solved&&ctx.encounter?'':`<aside class="play-sidebar">${solved?completionCard(p,a,ctx):`<div class="tool-grid">${btn('↶ Undo','undo','secondary',a.history.length&&!(expansion&&mechanicFor(p).noUndo?.(p))?'':'disabled')}${btn('Restart','restart','secondary')}${btn('Hint','hint','hint-button')}</div>${a.hintLevel?(expansion?expansionHintCard(a,hint,p):hintCard(p,a,hint,ctx)):''}`}</aside>`}
  </div><div class="feedback ${hint.type==='deadend'&&!solved?'deadend':''}" role="status" aria-live="polite">${esc(feedback)}</div>`;
}
function expansionHintCard(a,hint,p){
  // A 'note' hint (Proofs evidence puzzles) shows the authored hints by level and never an answer.
  return `<section class="hint-card" aria-label="Hint"><p>${esc(hint.type==='note'?p.hints[Math.min(a.hintLevel,p.hints.length)-1]:a.hintLevel===1&&a.moves===0?p.hints[0]:hint.text||'Check your current choices.')}</p>${a.hintLevel>=2&&hint.type==='deadend'?btn('Undo','rescue','secondary'):a.hintLevel>=3&&hint.type==='move'?btn('Apply hint','apply-hint','secondary'):''}</section>`;
}
function tileBoard(p,a,ctx){
  const isL=p.tileShape==='l-tromino',selection=ctx.tileSelection||[];
  const occupied=new Map();
  a.board.forEach((pair,index)=>pair.forEach(cell=>occupied.set(cell,index)));
  const position=cell=>`grid-row:${Math.floor(cell/p.cols)+1};grid-column:${cell%p.cols+1}`;
  const cells=Array.from({length:p.rows*p.cols},(_,cell)=>{
    if(!p.cells.includes(cell))return `<span class="garden-hole" style="${position(cell)}" data-cell="${cell}" aria-hidden="true"></span>`;
    const index=occupied.get(cell),planted=index!==undefined,checker=(cell%p.cols+Math.floor(cell/p.cols))%2;
    const chosen=selection.includes(cell);
    return `<button class="garden-cell checker-${checker} ${planted?'planted':''} ${chosen?'selected':''} ${ctx.highlighted?.includes(cell)?'hinted':''}" style="${position(cell)}" data-action="tile-cell" data-cell="${cell}" data-focus="cell-${cell}" aria-label="Row ${Math.floor(cell/p.cols)+1}, column ${cell%p.cols+1}${planted?`, tile ${index+1}; tap to lift`:chosen?', selected':', empty patch'}" aria-pressed="${chosen}"><span>${planted?index+1:chosen?'•':''}</span></button>`;
  }).join('');
  // Paint each domino once across both grid tracks. Cell buttons stay square and
  // accessible; clicking the painted gap also lifts the same tile.
  const dominoes=a.board.map((pair,index)=>{
    if(isL)return pair.map(cell=>`<span class="garden-domino garden-l-cell tile-color-${index%6}" style="${position(cell)}" aria-hidden="true"></span>`).join('');
    const first=Math.min(...pair),horizontal=Math.floor(pair[0]/p.cols)===Math.floor(pair[1]/p.cols);
    return `<span class="garden-domino tile-color-${index%6}" style="grid-row:${Math.floor(first/p.cols)+1} / span ${horizontal?1:2};grid-column:${first%p.cols+1} / span ${horizontal?2:1}" data-action="tile-cell" data-cell="${first}" aria-hidden="true"></span>`;
  }).join('');
  const picture=`<span class="tile-piece-picture ${isL?'tile-piece-l':'tile-piece-domino'}" role="img" aria-label="${isL?'L-tromino, 3 squares':'Domino, 2 squares'}">${Array.from({length:isL?3:2},()=>'<i></i>').join('')}</span>`;
  return `<div class="tile-piece-guide">${picture}${a.board.length?'':`<span>Drag across ${isL?3:2} squares</span>`}</div><div class="tile-board ${ctx.checker?'show-checker':''}" style="--cols:${p.cols};--rows:${p.rows}" role="group" aria-label="Garden with ${p.cells.length} patches">${cells}${dominoes}</div>`;
}
function swapBoard(p,a,ctx){return `<div class="cup-board" style="--cups:${p.start.length}" role="group" aria-label="Cups and their homes">${a.board.map((token,index)=>`<div class="cup-position"><span class="position-number">${index+1}</span><button class="cup-button cup-color-${token} ${ctx.selected===index?'selected':''} ${ctx.highlighted?.includes(index)?'hinted':''}" data-action="cup" data-cell="${index}" data-focus="cup-${index}" aria-label="Position ${index+1}: cup ${String.fromCharCode(65+token)}; home is ${String.fromCharCode(65+p.target[index])}" aria-pressed="${ctx.selected===index}"><svg viewBox="0 0 100 108" aria-hidden="true"><path d="M23 13h54l11 80q-38 16-76 0z" fill="currentColor" stroke="#142b48" stroke-width="3"/><path d="M26 14q24 9 48 0" fill="none" stroke="#142b48" stroke-width="3"/></svg><span class="cup-identity"><b>${String.fromCharCode(65+token)}</b><i aria-hidden="true">${symbols[token]}</i></span></button><div class="cup-home ${token===p.target[index]?'home-matched':''}"><span aria-hidden="true">${symbols[p.target[index]]}</span> ${String.fromCharCode(65+p.target[index])}${token===p.target[index]?' ✓':''}</div></div>`).join('')}</div><div class="allowed-pairs"><div>${p.edges.map(([a,b])=>btn(`${a+1} ↔ ${b+1}`,'swap-pair','pair-button',`data-pair="${a},${b}" aria-label="Swap positions ${a+1} and ${b+1}"`)).join('')}</div></div>`;}
// On the road the six travelers are the cups: each finds the seat with their name.
const PARTY_ORDER=['pip','moss','rook','bea','fern','tumble'];
function partyBoard(p,a,ctx){const who=i=>PARTY_ORDER[i],name=i=>PARTY_NAMES[who(i)];return `<div class="cup-board party-board" style="--cups:${p.start.length}" role="group" aria-label="Travelers and their seats">${a.board.map((token,index)=>`<div class="cup-position"><span class="position-number">${index+1}</span><button class="cup-button party-seat ${ctx.selected===index?'selected':''} ${ctx.highlighted?.includes(index)?'hinted':''} ${token===p.target[index]?'seated':''}" data-action="cup" data-cell="${index}" data-focus="cup-${index}" aria-label="Seat ${index+1}: ${name(token)}; this is ${name(p.target[index])}’s seat" aria-pressed="${ctx.selected===index}">${media(slots.party(who(token)),`<svg viewBox="0 0 120 120" aria-hidden="true">${companionDrawing(who(token))}</svg>`,{key:`seat-${index}`})}</button><div class="cup-home seat-home ${token===p.target[index]?'home-matched':''}">${media(slots.party(who(p.target[index])),`<svg viewBox="0 0 120 120" aria-hidden="true">${companionDrawing(who(p.target[index]))}</svg>`,{key:`home-${index}`})}<span>${name(p.target[index])}${token===p.target[index]?' ✓':''}</span></div></div>`).join('')}</div><div class="allowed-pairs"><div>${p.edges.map(([a,b])=>btn(`${a+1} ↔ ${b+1}`,'swap-pair','pair-button',`data-pair="${a},${b}" aria-label="Swap seats ${a+1} and ${b+1}"`)).join('')}</div></div>`;}
function hintCard(p,a,hint,ctx={}){const party=ctx.encounter?.party;return `<section class="hint-card" aria-label="Hint">${a.hintLevel===1?`<p>${esc(party?'Look at the names under each seat. Who needs to move, and which allowed swap helps?':a.moves===0?p.hints[0]:p.mechanic==='tile'?'Look for an empty patch with only one possible tile placement. If there is none, try a patch near the edge.':'Look at the home labels. Where does one cup need to go, and which allowed swap helps it get there?')}</p>`:''}${hint.type==='deadend'?`<p>This cannot be completed. Undo to try another move.</p>${btn('Undo','rescue','secondary')}`:hint.type==='move'&&a.hintLevel>=2?`<p>${p.mechanic==='tile'?`The glowing patches at ${hint.pair.map(cell=>`row ${Math.floor(cell/p.cols)+1}, column ${cell%p.cols+1}`).join('; ')} can share a tile.`:`Try swapping ${party?'seats':'positions'} ${hint.pair[0]+1} and ${hint.pair[1]+1}.`}</p>${a.hintLevel>=3?btn('Apply hint','apply-hint','secondary'):''}`:''}</section>`;}
function completionCard(p,a,ctx){
  const list=p.band==='proofs'?ctx.pack.puzzles.filter(q=>q.band==='proofs'&&q.libraryFamily===p.libraryFamily).sort((a,b)=>a.number-b.number):isExpansion(p)?ctx.pack.puzzles.filter(q=>q.mechanic===p.mechanic).sort((a,b)=>a.number-b.number):listFor(ctx.pack.puzzles,p.band);
  const next=list[list.findIndex(q=>q.id===p.id)+1];
  return `<section class="completion-card" aria-label="Puzzle completed"><h2 tabindex="-1" id="completion-heading">Solved</h2>${next?btn('Next puzzle →','open-puzzle','primary wide',`data-id="${next.id}"`):btn('Puzzles','library','primary wide')}${btn('Replay','replay','text-button')}</section>`;
}
function sourceLinks(pack,ids){return ids.map(id=>pack.sources.find(s=>s.id===id)).filter(Boolean).map(s=>s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a>`:`<span>${esc(s.title)}${s.contribution?` — ${esc(s.contribution)}`:''}</span>`).join(' · ');}
export function notesHTML(p,pack){return `<p class="note-idea">${esc(p.idea)}</p>${isExpansion(p)?`<h3>Readiness and rules</h3><p>${esc(p.prerequisites)}</p><ul>${p.rules.map(rule=>`<li>${esc(rule)}</li>`).join('')}</ul>${p.provenance?`<p>${esc(p.provenance)}</p>`:''}`:''}<h3>What to notice</h3><p>${esc(p.parent.notice)}</p><h3>Ask together</h3><p>“${esc(p.parent.prompt)}”</p><h3>The mathematics</h3><p>${esc(p.parent.explanation)}</p><h3>A bigger question</h3><p>${esc(p.parent.extension)}</p><h3>Where this leads</h3><p>${esc(p.parent.connection)}</p><details data-view-key="hints-${esc(p.id)}"><summary>Authored starting-board hints</summary><ol>${p.hints.map(h=>`<li>${esc(h)}</li>`).join('')}</ol><p>These describe the starting puzzle. In play, concrete move hints are computed from the current board.</p></details><p class="sources">${sourceLinks(pack,p.parent.sourceIds)}</p>`;}
export function catalogHTML(band,pack,pr){return listFor(pack.puzzles,band).map((p,i)=>`<details class="puzzle-notes" data-view-key="notes-${esc(p.id)}"><summary><span>${String(i+1).padStart(2,'0')}</span> ${esc(p.title)} <small>${esc(p.familyTitle||(p.mechanic==='tile'?'Tile garden':'Cup swaps'))}</small></summary><div class="note-body">${notesHTML(p,pack)}${pr?btn('Open this puzzle','open-puzzle','secondary',`data-id="${p.id}"`):''}</div></details>`).join('');}
export function parentView(state,pr,pack,offlineStatus='Preparing offline play…',catalogBand=pr?.band||'k1'){return `<section class="intro"><div><h1>Grown-ups</h1></div></section><div class="parent-layout"><section class="panel"><h2>Explorers & saves</h2><p class="muted spaced">Each explorer has a separate save. Nicknames and progress stay in this browser. Export occasionally: clearing browser data or losing the device can lose these saves.</p>${state.profiles.length?state.profiles.map(pr=>`<div class="parent-profile"><span class="avatar" aria-hidden="true">${avatars[pr.avatar]}</span><div><strong>${esc(pr.name)}</strong><p class="muted">Grades ${BANDS[pr.band].label} · ${count(pack.puzzles,pr)}/24 explored · ${listFor(pack.puzzles,pr.band).filter(p=>pr.attempts[p.id]?.completed&&pr.attempts[p.id]?.helpUsed).length} with hints · ${pack.puzzles.filter(p=>isExpansion(p)&&p.band==='all'&&pr.attempts[p.id]?.completed).length}/${pack.puzzles.filter(p=>isExpansion(p)&&p.band==='all').length} family puzzles${pack.puzzles.some(p=>p.band==='proofs')?` · ${pack.puzzles.filter(p=>p.band==='proofs'&&pr.attempts[p.id]?.completed).length}/${pack.puzzles.filter(p=>p.band==='proofs').length} proofs (${pack.puzzles.filter(p=>p.band==='proofs'&&pr.attempts[p.id]?.completed&&pr.attempts[p.id]?.helpUsed).length} with hints)`:''}</p></div>${btn('Open','choose-profile','secondary small',`data-id="${esc(pr.id)}"`)}${btn('Delete','delete-profile','quiet small',`data-id="${esc(pr.id)}"`)}</div>`).join(''):'<p class="spaced">No explorers yet. Create one to start a separate save.</p>'}<div class="button-row">${btn('New explorer','profiles','secondary')}${btn('Export saves','export','secondary')}${btn('Import backup','import','secondary')}</div><input id="import-file" type="file" accept="application/json,.json" hidden><div class="settings-row">${btn('Clear all local data','clear','danger small')}${pr?`<label><input id="sound-toggle" type="checkbox" ${pr.sound?'checked':''}> Read instructions aloud for ${esc(pr.name)}</label>`:''}</div><p class="muted small-copy">Imported saves become new explorers. Existing saves are kept.</p></section><section class="panel install-panel"><h2>Play on iPad</h2><p id="offline-status" role="status">${esc(offlineStatus)}</p><ol><li>Open this app’s HTTPS address in Safari.</li><li>Tap Share, then <strong>Add to Home Screen</strong>.</li><li>Turn on <strong>Open as Web App</strong>, then Add.</li><li>Open the new icon online. Check offline status here in <strong>Grown-ups</strong>.</li></ol><p>Then try Airplane Mode and reopen it. All ${pack.puzzles.length} puzzles are included offline.</p><p class="muted spaced">Speech depends on voices installed on your device. Full instructions are available in How to play.</p><p class="sources"><a href="https://support.apple.com/guide/ipad/open-as-web-app-ipad8f1f7a29/ipados" target="_blank" rel="noopener noreferrer">Apple’s installation guide</a></p></section></div><section class="parent-research panel"><h2>Mathematics</h2><div class="research-columns"><div><h3>Tile gardens → structure and possibility</h3><p>A domino pairs neighboring cells; an L-tromino covers three corners of a 2×2 square. Small gardens make constraints, decomposition, and checkerboard arguments tangible. Domino gardens connect to undergraduate matching theory; L gardens use exact cover and decomposition. For dominoes and lozenges, research studies height functions, local changes between tilings, and the shapes that emerge in random tilings.</p><p class="muted spaced">A coloring argument can prove impossibility. Equal color counts alone do not guarantee a tiling. Every core garden here is solvable; some Proofs gardens are not.</p></div><div><h3>Cup swaps → transformations and routes</h3><p>The cups form a permutation. Allowed swaps make a network of arrangements. Children try routes and notice what one move can change. Older explorers encounter cycles, inversions, and sorting with restricted moves—the small relatives of token-swapping and random-walk research.</p><p class="muted spaced">For three distinct cups, uniformly random swaps return to the starting order after 6 swaps on average. That is a random-return result, not the minimum needed to solve a scrambled row.</p></div></div><div class="research-columns">${(pack.families||[]).map(f=>`<div><h3>${esc(f.title)}</h3><p>${esc(f.mathematics)}</p></div>`).join('')}</div><details class="research-sources" data-view-key="research-sources"><summary>Research & undergraduate reading</summary>${pack.sources.map(s=>`<p><span class="source-kind">${esc(s.kind)}</span> ${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a>`:esc(s.title)}</p>`).join('')}</details></section><section class="panel paper-section"><div class="section-top"><div><h2>Paper activities</h2></div>${btn('Print activities','print','secondary')}</div><ol class="paper-list"><li><strong>Two ways to garden.</strong> Draw a 2×2 square and cut two paper dominoes. Find both coverings. What moves when you switch between them?</li><li><strong>Make a color argument.</strong> Color a 4×4 checkerboard and remove two opposite corners. Can dominoes cover it? Count the colors and explain why each domino needs one of each.</li><li><strong>A missing square.</strong> Remove any cell from a 4×4 board. Cover it with five L-trominoes. Place a central L so each 2×2 quadrant has exactly one missing cell. How could the same idea work on an 8×8 board?</li><li><strong>Map the six arrangements.</strong> Label three cups A, B, C. List all six orders. Connect orders that differ by one swap. Why does every swap move to the other side of a two-coloring?</li><li><strong>Neighbors only.</strong> Start three cups at C, B, A. Only neighbors may swap. How many moves are needed? Now allow any pair. What changed?</li><li><strong>Come back home.</strong> Roll a die: 1–2 swaps positions 1 and 2, 3–4 swaps 1 and 3, 5–6 swaps 2 and 3. Start at ABC and count until the first return. Repeat, keeping every long trial. The theoretical mean is 6; a short experiment need not be close.</li></ol></section><section class="panel catalog"><div class="section-top"><div><h2>Puzzle notes</h2></div><label>Trail <select id="catalog-band" data-view-key="catalog-band" data-focus="catalog-band">${['k1','23','45','all',...(pack.puzzles.some(p=>p.band==='proofs')?['proofs']:[])].map(key=>[key,key==='all'?{label:'All family adventures'}:key==='proofs'?{label:'Proofs'}:BANDS[key]]).map(([key,b])=>`<option value="${key}" ${key===catalogBand?'selected':''}>${key==='all'||key==='proofs'?'':'Grades '}${b.label}</option>`).join('')}</select></label></div><div id="catalog-list">${catalogHTML(catalogBand,pack,pr)}</div></section><p class="muted scope-note">Grade bands are starting points. Family playtesting found sampled early tile gardens too easy; cup swaps worked better. The ten new families still need playtesting and difficulty calibration. There are no timers, purchases, accounts, ads, or cloud saves.</p>`;}

const familySymbols={toggle:'☀',clock:'◷',billiard:'↗',route:'♧',latin:'▦',code:'◐',nim:'●',color:'◆',jug:'♒',weigh:'⚖'};
function expansionMap(pr,puzzles){
  const families=[...new Set(puzzles.filter(isExpansion).map(p=>p.mechanic))];
  const total=puzzles.filter(isExpansion),done=total.filter(p=>pr.attempts[p.id]?.completed).length;
  return `<section class="family-adventures"><div class="section-top"><div><p class="eyebrow">Ten more ways to explore · ${done} / ${total.length} discovered</p><h2>Choose a puzzle family.</h2><p class="muted">Six steps in each family. Start anywhere, skip the introduction, and keep going as far as you like. These adventures are shared across all grade trails.</p></div></div><div class="family-list">${families.map(id=>{const list=total.filter(p=>p.mechanic===id).sort((a,b)=>a.number-b.number);return `<details class="family-section panel"><summary><span aria-hidden="true">${familySymbols[id]}</span><strong>${esc(list[0].familyTitle)}</strong><span>${list.filter(p=>pr.attempts[p.id]?.completed).length} / 6</span></summary><p class="muted spaced">${esc(list[0].prerequisites)}</p><div class="puzzle-grid">${list.map(p=>{const a=pr.attempts[p.id];return `<button class="puzzle-card ${p.mechanic} ${a?.completed?'complete':''}" data-action="open-puzzle" data-id="${esc(p.id)}" aria-label="${p.number}. ${esc(p.title)}. ${a?.completed?'Completed':a?'In progress':'Ready to explore'}"><span class="puzzle-top"><span class="mechanic-symbol" aria-hidden="true">${familySymbols[id]}</span><span>${a?.completed?'✓':p.number}</span></span><strong>${esc(p.title)}</strong><small>${p.number===1?'Entry · ':p.number>=5?'Stretch · ':''}${a?.completed?'Explored':a?'Started':'Ready to explore'}</small></button>`;}).join('')}</div></details>`;}).join('')}</div></section>`;
}
// Campaign scenes wrap the original validators and controls without changing their rules.
export function playView(p,a,ctx){
 const e=ctx.encounter?.stop&&ctx.profile?ctx.encounter:null,solved=isSolved(p,a.board);
 return `<div data-puzzle-id="${esc(p.id)}" class="caravan-puzzle ${e?`lr-play mood-${esc(e.stop)}`:''} ${e&&solved?'lr-solved':''}" aria-label="${esc(p.familyTitle||(p.mechanic==='tile'?'Tile garden':'Cup swaps'))}">${e?encounterScene(e,ctx.profile,p,a,{reaction:ctx.reaction,changed:ctx.changed}):''}<div class="puzzle-workspace">${puzzleView(p,a,ctx)}</div></div>`;
}
